def wilson_lower(k: int, n: int, z: float = 1.96) -> float:
    if n == 0:
        return 0.0
    p = k / n
    denom = 1 + z**2 / n
    centre = (p + z**2 / (2*n)) / denom
    half = z * (p*(1-p)/n + z**2/(4*n**2))**0.5 / denom
    return max(0.0, centre - half)

